import { R, fig, type Concept } from "./kit";

/**
 * Real labelled drawings from the figure library (src/components/study/figures):
 * anatomy, synapses, drug actions, EEG and sleep, plotted curves and the set-ups
 * of classic studies. Each concept names one figure, the labels to light up and
 * a line on what to look at. Patterns are kept tight: a figure goes only where
 * the question is about the thing it draws.
 */

const B = ["biological"] as const;
const BX = ["biological", "cognitive", "clinical-psychiatry", "psychopathology", "perception-attention", "learning-motivation-emotion", "psychometrics-assessment"] as const;
const BC = ["biological", "clinical-psychiatry", "psychopathology", "psychopharmacology"] as const;
const PH = ["psychopharmacology", "clinical-psychiatry", "biological", "psychopathology"] as const;
const PER = ["perception-attention", "biological", "cognitive"] as const;
const STAT = ["statistics", "research-methods", "psychometrics-assessment"] as const;
const DEV = ["developmental", "cognitive", "history-systems"] as const;
const LRN = ["learning-motivation-emotion", "history-systems", "clinical-therapies", "developmental", "personality-theories"] as const;
const SOC = ["social", "research-methods", "ethics-law", "history-systems", "organisational", "ugc-paper1"] as const;
const CLIN = ["psychopathology", "clinical-psychiatry", "health", "clinical-therapies", "counselling"] as const;

export const FIGS: Concept[] = [
  /* ------------------------------------------------ the brain, whole */
  fig("fig-brain-lateral", R(BX, /central sulcus|lateral (sulcus|fissure)|sylvian|fissure of rolando|rolandic|precentral gyrus|postcentral gyrus|superior temporal gyrus|middle frontal gyrus|inferior frontal gyrus|supramarginal gyrus|four lobes|lobes of the (brain|cerebrum|cerebral cortex)|gyri and sulci|gyrus and sulcus/i), "brain-lateral", [], "Find the central sulcus first: in front of it is the frontal lobe with the motor strip, behind it the parietal lobe with the sensory strip. The lateral sulcus has the temporal lobe below it, and the occipital lobe sits at the back."),
  fig("fig-brain-medial", R(BX, /corpus callosum|septum pellucidum|cingulate gyrus|calcarine|parieto.?occipital sulcus|mid.?sagittal|medial surface of the (brain|hemisphere)|pineal gland|massa intermedia/i, undefined, /split.brain|commissurotom|sperry|gazzaniga/i), "brain-medial", [], "Cut down the middle, the brain shows its deep parts: the corpus callosum arching over the thalamus, the hypothalamus and pituitary below, the pineal at the back, and the brainstem running down to the cerebellum."),
  fig("fig-brain-split", R(BX, /split.brain|commissurotom|callosotomy|sperry|gazzaniga/i), "brain-medial", ["cc"], "The corpus callosum is the bridge of about 200 million fibres between the hemispheres. Cutting it for severe epilepsy leaves each half working alone, so what one side sees the other cannot name."),
  fig("fig-brain-inferior", R([...BX, "health"], /cranial nerves?|olfactory nerve|oculomotor nerve|trochlear|trigeminal|abducens|facial nerve|vestibulocochlear|glossopharyngeal|vagus nerve|spinal accessory|hypoglossal|\bcn ?(iii|iv|vi|vii|viii|ix|xi|xii)\b|twelve (pairs of )?nerves/i), "brain-inferior", [], "Seen from below, the twelve cranial nerves leave the brain in order from front to back: smell and sight from the forebrain, eye movement nerves from the midbrain and pons, and the vagus and hypoglossal from the medulla."),
  fig("fig-brodmann", R(BX, /brodmann|\bareas? (4|6|8|9|10|17|18|19|22|39|40|41|42|44|45|46)\b.{0,30}(cortex|motor|visual|auditory|broca|wernicke|prefrontal|brodmann)/i), "brodmann", [], "Brodmann numbered cortex by its cell layers. Area 4 is primary motor, 3, 1 and 2 primary sensory, 17 primary visual, 41 and 42 primary auditory, 44 and 45 Broca's area and 22 Wernicke's area."),
  fig("fig-language-areas", R(BX, /broca|wernicke'?s? (area|aphasia)|arcuate fasciculus|conduction aphasia|transcortical (motor|sensory) aphasia|global aphasia|fluent aphasia|non.?fluent aphasia|expressive aphasia|receptive aphasia|angular gyrus|alexia|agraphia|gerstmann|lichtheim|planum temporale/i, undefined, /encephalopath|korsakoff|thiamine/i), "language-areas", ["broca", "wernicke", "arcuate"], "Broca's area in the left frontal lobe produces speech; Wernicke's area in the left temporal lobe understands it. The arcuate fasciculus joins them, so damage there spares both but ruins repetition: conduction aphasia."),
  fig("fig-prefrontal", R(BX, /dorsolateral prefrontal|\bdlpfc\b|orbitofrontal|ventromedial prefrontal|\bvmpfc\b|subgenual|anterior cingulate|frontopolar|phineas gage|parts of the prefrontal|prefrontal (regions|subdivisions|circuits?)|dysexecutive|frontal lobe syndrome|wisconsin card|\bwcst\b|trail making|tower of london|verbal fluency|go.?no.?go/i), "prefrontal", ["dlpfc", "lofc", "vmpfc", "acc"], "Three frontal syndromes map onto three regions: dorsolateral damage disorganises planning and set shifting, orbitofrontal damage disinhibits behaviour, and medial and anterior cingulate damage makes a person apathetic."),
  fig("fig-arteries", R([...BX, "health"], /(anterior|middle|posterior) cerebral artery|\b(aca|mca|pca)\b.{0,30}(stroke|infarct|territor|occlusion)|watershed|vascular territor|arterial territor|stroke.{0,40}(artery|territor)|lacunar|vascular dementia.{0,40}(artery|infarct)|multi.infarct|strategic infarct/i), "arterial-territories", ["aca", "mca", "pca"], "Each artery feeds its own part of the hemisphere. The middle cerebral artery supplies most of the outer surface, including face, arm and language areas; the anterior cerebral feeds the leg area along the midline; the posterior cerebral feeds vision at the back."),
  fig("fig-willis", R([...BX, "health"], /circle of willis|basilar artery|vertebral arter|internal carotid|communicating artery|berry aneurysm|subarachnoid ha?emorrhage/i), "circle-of-willis", [], "On the base of the brain the two internal carotids and the basilar artery are joined in a ring by communicating arteries, so one blocked vessel can be partly bypassed. Berry aneurysms form at its branch points."),
  fig("fig-vesicles", R(["biological", "developmental"], /neural tube|neural plate|prosencephalon|mesencephalon|rhombencephalon|telencephalon|diencephalon|metencephalon|myelencephalon|forebrain.{0,20}midbrain.{0,20}hindbrain|primary (brain )?vesicles|anencephal|spina bifida/i), "brain-vesicles", [], "The neural tube swells into three vesicles (forebrain, midbrain, hindbrain), then five. The telencephalon becomes the cerebral hemispheres and the diencephalon the thalamus and hypothalamus; the fluid space inside becomes the ventricles."),

  /* ------------------------------------------------ deep structures */
  fig("fig-coronal", R(BX, /claustrum|lentiform|grey and white matter|white matter and grey|coronal (section|slice|cut)|corona radiata/i), "coronal-section", ["caudate", "putamen", "pallidus", "thalamus", "capsule"], "A front-to-back slice shows grey matter on the outside and in deep islands. The caudate hugs the ventricle, the putamen and globus pallidus sit outside the internal capsule, and the thalamus lies in the middle."),
  fig("fig-capsule", R(BX, /internal capsule|capsulotomy|anterior limb|posterior limb|genu of the/i), "horizontal-section", ["alic", "genuic", "plic"], "Seen from above, the internal capsule is a V of white matter between the caudate, thalamus and lentiform nucleus. Its posterior limb carries motor fibres to the body; its anterior limb carries frontal loops and is the target of capsulotomy for severe OCD."),
  fig("fig-basal-ganglia", R(BX, /basal ganglia|caudate|putamen|globus pallidus|striatum|nucleus accumbens|corpus striatum|huntington'?s? (disease|chorea)|chorea\b|wilson'?s disease|hepatolenticular/i, undefined, /autosomal|inherit|heterozygous|probabilit|anticipation|genetic (mechanism|counsel|test)|\bcag\b|risk (is|of)|chance|penetrance|prairie vole|kayser/i), "basal-ganglia", ["caudate", "putamen", "pallidus", "nigra"], "The caudate is C-shaped, with a head, body and tail following the ventricle. With the putamen it forms the striatum, which takes in cortex and dopamine from the substantia nigra. Huntington's disease shrinks the caudate first."),
  fig("fig-bg-loop", R([...BX, "psychopharmacology"], /direct (and|or|vs\.?|versus) indirect|indirect pathway|direct pathway|subthalamic|hemiballism|(deep brain stimulation|\bdbs\b).{0,60}(parkinson|subthalamic|globus|\bgpi\b|\bstn\b|tremor|dystonia)|cortico.?striat|striato.?thalam|parkinson'?s?( disease)?.{0,40}(circuit|pathophysiolog|mechanism|loop)/i), "basal-ganglia-circuit", ["direct", "indirect", "da", "stn"], "Cortex drives the striatum. The direct pathway releases the thalamus and lets movement through; the indirect pathway, through the subthalamic nucleus, holds it back. Dopamine from the nigra boosts the first and quietens the second, so losing it in Parkinson's disease leaves movement braked."),
  fig("fig-homunculus", R(BX, /homunculus|somatotop|penfield|motor strip|sensory strip|cortical (magnification|representation)|precentral|postcentral|primary (motor|somatosensory) cortex/i), "homunculus", [], "Body parts are laid out along the motor strip (in front of the central sulcus) and the sensory strip (behind it), each sized by how much cortex it gets: the hands, lips and tongue are huge, the trunk tiny, and the leg sits on the inner surface."),
  fig("fig-ventricles", R(BX, /ventricles? of the brain|lateral ventricles?|third ventricle|fourth ventricle|cerebrospinal fluid|\bcsf\b|hydrocephalus|cerebral aqueduct|aqueduct of sylvius|foramen of monro|choroid plexus|arachnoid granulation|ventricular (enlargement|dilat|brain ratio)|enlarged (lateral )?ventricles|\bvbr\b/i, undefined, /arrhythm|tachycard|fibrillation|\bqtc?\b|cardiac|heart|vdrl|treponem|rt.quic|5.hiaa|serology|csf (tests?|levels?|concentrations?|biomarkers?|analysis|examination|hypocretin)|lumbar puncture|\bcrh\b/i), "ventricles", ["lateral", "v3", "aqueduct", "v4", "choroid"], "Fluid is made by the choroid plexus in the lateral ventricles, flows through the third ventricle and the narrow aqueduct into the fourth, and leaves to bathe the brain. A block at the aqueduct swells the ventricles above it; in schizophrenia the lateral and third ventricles are slightly larger on average."),
  fig("fig-hippocampus", R(BX, /dentate gyrus|\bca1\b|\bca3\b|cornu ammonis|ammon'?s horn|trisynaptic|perforant path|mossy fib|schaffer|subiculum|entorhinal|hippocampal (formation|sclerosis|neurogenesis|atrophy|volume|circuit)|mesial temporal sclerosis|place cells/i), "hippocampus", ["dg", "ca3", "ammon", "subiculum"], "Information enters from the entorhinal cortex by the perforant path to the dentate gyrus, then mossy fibres to CA3, Schaffer collaterals to CA1 and out through the subiculum: the trisynaptic circuit where long-term potentiation was first found."),
  fig("fig-limbic", R(BX, /papez|limbic (system|lobe|circuit)|mammillothalamic|fornix|cingulate gyrus|parahippocampal gyrus|cingulum|anterior (nucleus of the )?thalamus|mammillary bod/i), "limbic-system", ["hippocampus", "fornix", "mammillary", "anteriorthal", "cingulate"], "Follow the Papez circuit: hippocampus, along the fornix to the mammillary body, up the mammillothalamic tract to the anterior thalamus, on to the cingulate gyrus and back to the hippocampus. Damage at the mammillary bodies and thalamus underlies Korsakoff's memory loss."),
  fig("fig-amygdala", R([...BX, "clinical-therapies"], /amygdala|low road|high road|ledoux|fear (conditioning|circuit|extinction|learning)|basolateral|central nucleus|kl[uü]ver.?bucy|urbach|threat (detection|response)/i), "amygdala-fear", ["amygdala", "low", "high", "vmpfc"], "Danger reaches the amygdala two ways: a fast rough route straight from the thalamus and a slower detailed one through the cortex. The amygdala then drives the hypothalamus and brainstem into a fear response, while the ventromedial prefrontal cortex and hippocampus calm it, which is how extinction works."),
  fig("fig-hypothalamus", R([...BX, "health"], /supraoptic|paraventricular|arcuate nucleus|ventromedial (nucleus|hypothalamus)|lateral hypothalamus|lateral hypothalamic|preoptic|nuclei of the hypothalamus|hypothalamic nuclei|dorsomedial nucleus|satiety cent|feeding cent|hypothalamic (hyperphagia|lesion)|leptin|ghrelin|neuropeptide y|\bnpy\b|orexigenic|anorexigenic|\bpomc\b|\bagrp\b/i), "hypothalamus", ["lateral", "vmn", "arcuate", "pvn", "scn"], "The hypothalamus is a cluster of small nuclei. The lateral area starts eating and the ventromedial nucleus stops it; the arcuate nucleus reads leptin and ghrelin; the paraventricular nucleus makes CRH and oxytocin; the suprachiasmatic nucleus is the body clock."),
  fig("fig-scn", R([...BX, "health"], /suprachiasmatic|\bscn\b|master clock|retinohypothalamic|melanopsin|delayed sleep(.wake)? phase|advanced sleep(.wake)? phase|circadian rhythm sleep|non.24/i), "hypothalamus", ["scn", "chiasm"], "The suprachiasmatic nucleus sits just above the optic chiasm, where light-sensing retinal cells can reach it directly. Left in constant darkness it runs a little over 24 hours; morning light resets it each day."),
  fig("fig-ras", R([...BX, "personality-theories"], /reticular (formation|activating)|\bras\b|ascending reticular|\baras\b|moruzzi|magoun|brainstem arousal|arousal system/i), "ras", ["rf", "thalamus", "cortex"], "The reticular formation runs up the core of the brainstem and keeps the cortex awake through the thalamus and through the hypothalamus and basal forebrain. Moruzzi and Magoun woke sleeping cats by stimulating it; damage gives coma. Eysenck linked introversion to a more easily aroused system."),

  /* ------------------------------------------------ brainstem, cerebellum, cord */
  fig("fig-midbrain", R(BX, /midbrain|mesencephalon|superior colliculus|periaqueductal|red nucleus|cerebral peduncle|tectum|tegmentum|weber'?s syndrome|parinaud/i, undefined, /forebrain.{0,20}midbrain.{0,20}hindbrain|neural tube|hallucinat/i), "midbrain-section", ["colliculus", "pag", "red", "nigra", "vta"], "A slice across the midbrain: the superior colliculi on the roof for eye movements, the periaqueductal grey round the aqueduct for pain control and defence, the red nucleus, and the dark substantia nigra beside the ventral tegmental area, the two dopamine sources."),
  fig("fig-pons", R(BX, /\bpons\b|pontine|locus c(o)?eruleus|medial longitudinal fasciculus|internuclear ophthalmoplegia|central pontine myelinolysis|osmotic demyelination|locked.in syndrome/i), "pons-section", ["lc", "raphe", "basilar", "cst"], "A slice across the upper pons: the locus coeruleus near the floor of the fourth ventricle (noradrenaline), the raphe in the midline (serotonin), and below them the basilar pons carrying motor fibres. Damage to the basilar pons with the top spared gives the locked-in syndrome."),
  fig("fig-medulla", R(BX, /medulla oblongata|(?<!adrenal )medulla\b|solitary (nucleus|tract)|nucleus ambiguus|area postrema|chemoreceptor trigger zone|vomiting cent|inferior olive|pyramidal decussation|lateral medullary|wallenberg/i), "medulla-section", ["nts", "dmnx", "ambiguus", "pyramid", "olive"], "A slice across the medulla: the solitary nucleus takes in taste and signals from the gut and heart, the dorsal vagal nucleus and nucleus ambiguus send out the vagus, and the pyramids carry motor fibres that cross just below."),
  fig("fig-cerebellum", R(BX, /cerebell|vermis|purkinje (cells?|neurons?)|dentate nucleus|intention tremor|dysdiadochokinesia|dysmetria|past.pointing|truncal ataxia|ataxic gait/i), "cerebellum", ["vermis", "hemisphere", "dentate", "arbor"], "The midline vermis controls balance and posture, so alcohol damage there gives a wide-based gait. The hemispheres coordinate the limbs on the same side, so damage gives intention tremor and clumsy rapid movements. The dentate nucleus is its main exit."),
  fig("fig-spinal-cord", R([...BX, "health"], /spinal cord|dorsal columns?|spinothalamic|corticospinal|dorsal root|ventral root|anterior horn|ventral horn|dorsal horn|brown.?s[eé]quard|tabes dorsalis|subacute combined|syringomyelia|pyramidal tract|motor neuron disease|upper motor neuron|lower motor neuron|babinski|extensor plantar|fasciculation/i), "spinal-cord", ["droot", "vroot", "gracilis", "spinothal", "lcst", "ventralhorn"], "In a slice of the cord, sensation enters by the dorsal root and movement leaves by the ventral root. The dorsal columns carry fine touch and position, the spinothalamic tract pain and temperature, and the lateral corticospinal tract carries commands from the motor cortex down."),
  fig("fig-reflex", R(["biological", "learning-motivation-emotion", "health"], /reflex arc|knee.?jerk|patellar|stretch reflex|monosynaptic|muscle spindle|spinal reflex|deep tendon reflex|reciprocal inhibition.{0,30}(muscle|reflex)/i, undefined, /aplysia|gill/i), "reflex-arc", ["spindle", "sensory", "motor", "inter"], "Tap the tendon: the stretched muscle spindle fires a sensory neuron into the cord, which connects straight onto the motor neuron (one synapse) and the muscle contracts, while an interneuron relaxes the opposing muscle. The brain is not needed."),

  /* ------------------------------------------------ cells */
  fig("fig-neuron", R(BX, /dendrites?|cell body|\bsoma\b(?! cube)|axon hillock|axon terminals?|terminal (buttons?|boutons?)|parts of (a|the) neuron|structure of (a|the) neuron|neurons? (receive|conduct|transmit)/i), "neuron", ["dendrites", "soma", "hillock", "axon", "terminals"], "Signals come in at the dendrites, are summed at the cell body, and if they reach threshold at the axon hillock an action potential runs down the axon to the terminals, which release transmitter."),
  fig("fig-neuron-types", R(B, /multipolar|bipolar neurons?|unipolar neurons?|pseudo.?unipolar|pyramidal (cells?|neurons?)|types of neurons|classif(y|ication of) neurons|sensory neurons?.{0,40}motor neurons?/i), "neuron-types", [], "Neurons are named by how many processes leave the cell body: multipolar (most motor neurons and interneurons), bipolar (retina, smell), pseudounipolar (touch and pain nerves, cell body in the dorsal root ganglion) and pyramidal (the main output cells of the cortex)."),
  fig("fig-myelin", R([...BX, "developmental"], /myelin|saltatory|nodes? of ranvier|oligodendrocyte|schwann|demyelinat|multiple sclerosis|guillain|leukodystroph/i, undefined, /depression|crying|laughing|laughter|pseudobulbar|euphoria|fatigue|neuropsychiatric/i), "myelin", ["sheath", "node", "saltatory", "schwann", "oligo"], "Myelin is wrapped round the axon in layers, with gaps called nodes of Ranvier. The signal jumps from node to node, so it travels far faster. Schwann cells wrap one stretch of one nerve in the body; an oligodendrocyte wraps many axons in the brain and cord."),
  fig("fig-glia", R(["biological", "psychopharmacology"], /\bglia|glial|astrocyte|microglia|ependym|blood.brain barrier|neuroglia|end.?feet/i), "glia", ["astrocyte", "endfeet", "oligo", "microglia"], "Glia outnumber neurons. Astrocytes wrap capillaries with their end-feet and help form the blood-brain barrier, oligodendrocytes make myelin, microglia are the brain's immune cells, and ependymal cells line the ventricles."),

  /* ------------------------------------------------ the synapse */
  fig("fig-synapse", R(BX, /synaptic cleft|synaptic vesicles?|presynaptic (terminal|membrane|neuron)|postsynaptic (density|receptors?|membrane|neuron)|exocytosis|chemical synapse|synaptic transmission|steps? (of|in) (synaptic|neuro)transmission|calcium.{0,30}(vesicle|release)|neurotransmitter release/i), "synapse", ["vesicle", "cachannel", "fusion", "receptor", "transporter"], "Follow one message: the spike opens calcium channels, vesicles fuse and release transmitter into the cleft, it binds receptors on the spine, and it is cleared by a reuptake transporter or broken down. An autoreceptor on the ending tells it how much has been released."),
  fig("fig-synapse-reuptake", R(BX, /reuptake|transporters?\b.{0,40}(serotonin|dopamine|noradrenaline|norepinephrine|transmitter)|terminat(e|ion|es) (the )?(action|signal)|monoamine oxidase|\bmao\b/i, undefined, /\bssri|tricyclic|maoi|cyp/i), "synapse", ["transporter", "mito", "autoreceptor"], "Most transmitter is not destroyed in the cleft: a transporter pumps it back into the ending, where it is reloaded or broken down by MAO on the mitochondria. Acetylcholine is the exception, split in the cleft by an enzyme."),
  fig("fig-nmj", R([...BX, "psychopharmacology"], /neuromuscular junction|end.?plate|myasthenia|botulinum|curare|succinylcholine|suxamethonium|lambert.?eaton|muscle relaxant|nicotinic (acetylcholine )?receptors? (at|on) (the )?muscle/i, undefined, /seizure threshold/i), "nmj", ["terminal", "vesicles", "nachr", "ache", "folds"], "At the neuromuscular junction acetylcholine crosses to nicotinic receptors on folds of the muscle membrane and is split at once by acetylcholinesterase. Myasthenia gravis attacks the receptors; botulinum toxin stops release; the muscle relaxant given in ECT blocks the junction."),
  fig("fig-receptor-families", R([...BX, "psychopharmacology"], /ionotropic|metabotropic|ligand.gated|g.protein.coupled|\bgpcrs?\b|ion channel receptors?|fast (and|vs\.?|versus) slow (synaptic )?(transmission|receptors?)|two (types|families) of receptors?/i), "receptor-families", [], "Two kinds of receptor: an ion channel receptor opens a pore in milliseconds (glutamate AMPA, GABA-A, nicotinic), while a G protein coupled receptor sets off a G protein, an enzyme and second messengers, slower but longer lasting (dopamine, serotonin except 5-HT3, muscarinic)."),
  fig("fig-gpcr", R([...BX, "psychopharmacology"], /g.protein|adenylyl cyclase|adenylate cyclase|\bcamp\b|cyclic amp|seven.transmembrane|second messengers?|protein kinase|phosphoinositide|\bip3\b|\bdag\b|g.?alpha subunit|gα/i, undefined, /lithium/i), "gpcr-scene", [], "The receptor chain crosses the membrane seven times. When the transmitter binds, the receptor switches on a G protein; its alpha part turns on adenylyl cyclase, which makes cAMP, the second messenger that activates protein kinases inside the cell."),

  /* ------------------------------------------------ transmitter systems */
  fig("fig-da-pathways", R(BC, /mesolimbic|mesocortical|nigrostriatal|tuberoinfundibular|dopamine (pathways?|tracts?|projections|systems?)|ventral tegmental|\bvta\b|dopamine hypothesis|aberrant salience/i), "dopamine-pathways", ["nigrostriatal", "mesolimbic", "mesocortical", "tuberoinfundibular"], "Four dopamine pathways: nigrostriatal (movement, so blocking it gives stiffness and tremor), mesolimbic (reward, overactive in positive symptoms), mesocortical (thinking and drive, underactive in negative symptoms) and tuberoinfundibular (holds prolactin down)."),
  fig("fig-da-prolactin", R(PH, /^(?=[\s\S]*(hyperprolactin|prolactin|galactorrh|amenorrh|gynaecomast|gynecomast))(?=[\s\S]*(antipsychotic|dopamine|\bd2\b|risperidone|amisulpride|sulpiride|haloperidol|paliperidone|aripiprazole|tuberoinfundibular))/i), "dopamine-pathways", ["tuberoinfundibular", "arcuate"], "Dopamine from the arcuate nucleus runs down the tuberoinfundibular pathway to the pituitary and keeps prolactin release switched off. Blocking D2 receptors there lifts the brake, so prolactin rises: missed periods, breast milk, sexual problems and bone loss."),
  fig("fig-da-eps", R(PH, /extrapyramidal|\beps\b|parkinsonism|acute dystonia|akathisia|tardive dyskinesia|drug.induced (parkinson|movement)|oculogyric|torticollis/i, undefined, /lewy|hamilton|verbigeration/i), "dopamine-pathways", ["nigrostriatal", "snc", "striatum"], "Movement side effects come from the nigrostriatal pathway: blocking D2 receptors in the striatum mimics the dopamine loss of Parkinson's disease, giving stiffness, tremor, dystonia and restlessness."),
  fig("fig-5ht", R(BC, /raphe|serotonin(ergic)? (neurons|projections|system|pathways?|cell bodies)|5.ht (neurons|projections|system|cell bodies)/i), "serotonin-projections", ["dorsal", "median", "cortex", "limbic"], "Almost all the brain's serotonin comes from the raphe nuclei along the midline of the brainstem. The upper raphe send fibres to the whole forebrain; the lower raphe send them to the cerebellum and down the spinal cord, where they damp pain."),
  fig("fig-na", R([...BC, "learning-motivation-emotion"], /locus c(o)?eruleus|noradrenergic (neurons|system|projections|pathways?|hyperactivity|surge)|norepinephrine (system|neurons|projections)|noradrenaline (system|neurons|projections|pathways?)|(clonidine|lofexidine|yohimbine).{0,80}(noradrenal|norepineph|alpha.?2)|(opioid withdrawal|panic).{0,80}(noradrenal|norepineph)/i), "noradrenaline-projections", ["lc", "cortex", "limbic", "spinal"], "A small cluster in the pons, the locus coeruleus, sends noradrenaline to almost the whole brain and down the spinal cord. It fires with alertness and alarm, falls silent in REM sleep and is overactive in opioid withdrawal, which is why clonidine and lofexidine help."),
  fig("fig-ach", R([...BC, "cognitive"], /nucleus basalis|meynert|basal forebrain|cholinergic (hypothesis|neurons|projections|system|pathways?|deficit|loss)|medial septum|pedunculopontine|laterodorsal tegmental|(donepezil|rivastigmine|galantamine|cholinesterase inhibitors?).{0,80}(acetylcholine|cholinergic|mechanism|breakdown|nucleus basalis)|delirium.{0,80}(acetylcholine|cholinergic deficien)/i), "cholinergic-projections", ["nbm", "cortex", "septum-ach", "hippocampus"], "The nucleus basalis of Meynert sends acetylcholine to the whole cortex and the medial septum sends it to the hippocampus. These cells die early in Alzheimer's disease, which is why cholinesterase inhibitors give a modest lift to memory."),
  fig("fig-sleep-centres", R([...BC, "cognitive", "health"], /\bvlpo\b|ventrolateral preoptic|orexin|hypocretin|tuberomammillary|flip.?flop|sleep.?wake (switch|centres?|regulation|system)|narcolep|cataplexy|suvorexant|lemborexant|daridorexant|wake.promoting|histamin(e|ergic).{0,40}(wake|arousal|sleep|drows|sedat)/i), "sleep-centres", ["vlpo", "orexin", "tmn", "lc", "raphe"], "Sleep and waking work like a switch. Wake centres (histamine, noradrenaline, serotonin, acetylcholine) and the sleep-promoting VLPO inhibit each other; orexin neurons hold the switch on wake. Losing orexin neurons gives narcolepsy, and orexin blockers are a newer class of sleeping tablet."),
  fig("fig-hpa", R(["biological", "clinical-psychiatry", "psychopathology", "learning-motivation-emotion", "health"], /\bhpa\b|hypothalamic.pituitary.adrenal|\bcrh\b|\bcrf\b|\bacth\b|corticotrop|cortisol|glucocorticoid|dexamethasone (suppression|test)|adrenal cortex|cushing|addison/i), "hpa-axis", ["pvn", "crh", "acth", "adrenal", "feedback"], "The stress hormone chain: the hypothalamus releases CRH, the pituitary releases ACTH, the adrenal cortex releases cortisol, and cortisol feeds back on the hippocampus, hypothalamus and pituitary to switch the chain off. In melancholic depression this brake is weak."),
  fig("fig-endocrine", R(["biological", "health", "learning-motivation-emotion", "developmental"], /endocrine (gland|system)|thyroid|parathyroid|thymus|pancrea|adrenal glands?|gonads?|exocrine|thyroxine|hypothyroid|hyperthyroid|graves|cretinism|ductless glands?|glands?.{0,30}hormones?|hormones?.{0,30}(secreted|released|produced) by/i), "endocrine", [], "The endocrine glands release hormones into the blood: hypothalamus, pituitary and pineal in the head, thyroid and parathyroids in the neck, thymus, adrenals, pancreas and the ovaries or testes. The pituitary below the hypothalamus directs most of the others."),
  fig("fig-pituitary", R(["biological", "learning-motivation-emotion", "health", "psychopharmacology"], /pituitary|neurohypophysis|adenohypophysis|(oxytocin|vasopressin).{0,60}(pituitary|hypothalam|supraoptic|paraventricular|released from|synthesi[sz]ed)|antidiuretic|portal (system|vessels|blood)|releasing hormones?|growth hormone|gnrh|diabetes insipidus|siadh|syndrome of inappropriate/i, undefined, /prolactin|\bhpa\b|cortisol|\btsh\b/i), "pituitary", ["son", "pvn", "tract", "posterior", "portal", "anterior"], "The two lobes are linked to the hypothalamus differently. The posterior lobe is made of nerve endings from the supraoptic and paraventricular nuclei that release oxytocin and vasopressin; the anterior lobe receives releasing hormones through portal blood vessels."),
  fig("fig-autonomic", R([...BX, "health", "psychopharmacology"], /sympathetic (nervous|division|branch|chain|outflow)|parasympathetic|autonomic nervous|fight.or.flight|rest and digest|vagus|vagal|adrenal medulla|preganglionic|postganglionic|craniosacral|thoracolumbar|sympathetic and parasympathetic/i), "autonomic", ["cn3", "vagus", "sacral", "symout", "chain", "adrenal"], "The parasympathetic outflow leaves from the brainstem (mostly the vagus) and the sacral cord to slow the heart, narrow the pupils and run digestion. The sympathetic outflow leaves the thoracic and lumbar cord through the chain ganglia to speed the heart, widen the pupils and release adrenaline."),
  fig("fig-gut-brain", R(["biological", "health", "psychopathology", "clinical-psychiatry", "psychopharmacology"], /gut.brain|microbio|enteric nervous|probiotic|psychobiotic|gut bacteria|gut flora|enterochromaffin|irritable bowel/i), "gut-brain", ["vagus", "microbiota", "ec", "immune", "ens"], "The gut talks to the brain along the vagus nerve, through immune signals and through hormones. Gut bacteria shape these signals, and most of the body's serotonin is made by cells in the gut lining, not in the brain."),

  /* ------------------------------------------------ senses */
  fig("fig-eye", R([...PER, "psychopharmacology", "developmental"], /layers of the retina|retinal (layers|cells|ganglion|receptors|structure)|structure of the (eye|retina)|fovea|optic disc|blind spot|cornea|lens of the eye|crystalline lens|accommodation of the lens|photoreceptors?|rods? and cones?|cones? and rods?|\brhodopsin|ciliary (body|muscle)|vitreous|angle.closure glaucoma|glaucoma|aqueous humou?r|macula/i, undefined, /chlorpromazine|photosensitiv|optogenetic/i), "eye", ["cornea", "lens", "retina", "fovea", "disc"], "Light passes through the cornea and lens to the retina at the back. The fovea, packed with cones, gives sharp colour vision; the optic disc, where the nerve leaves, has no receptors and makes the blind spot."),
  fig("fig-visual-pathway", R(BX, /optic chiasm|optic tracts?|optic radiations?|lateral geniculate|\blgn\b|hemianopi|quadrantanopi|visual field (defects?|loss|cuts?)|meyer'?s loop|pie in the sky|homonymous|bitemporal hemianop|primary visual cortex|striate cortex|\bv1\b|calcarine|visual pathway/i, undefined, /ungerleider|mishkin|dorsal stream|ventral stream|two visual pathways/i), "visual-pathway", ["chiasm", "tract", "lgn", "radiation", "v1"], "Fibres from the inner half of each retina cross at the chiasm, so everything right of centre goes to the left brain. A pituitary tumour at the chiasm cuts both outer fields; a lesion behind it cuts the same half of both fields; a temporal lobe lesion cuts the upper quarter."),
  fig("fig-ear", R([...PER, "psychopharmacology"], /cochlea|ossicles?|malleus|incus|stapes|eardrum|tympanic|oval window|round window|semicircular canals?|vestibular (system|apparatus|organs?)|eustachian|inner ear|middle ear|conductive (hearing )?(loss|deafness)|sensorineural|basilar membrane|hair cells|organ of corti/i), "ear", ["drum", "malleus", "incus", "stapes", "cochlea", "canals"], "Sound moves the eardrum, the three ossicles pass it to the oval window, and fluid waves in the cochlea bend hair cells on the basilar membrane: high pitches near the base, low near the tip. The semicircular canals and vestibule sense head movement and balance."),
  fig("fig-auditory-pathway", R(PER, /auditory (pathway|cortex|nerve|nuclei)|medial geniculate|\bmgn\b|inferior colliculus|superior olive|olivary|lateral lemniscus|heschl|tonotop|sound locali[sz]ation|interaural/i, undefined, /fear|amygdala/i), "auditory-pathway", ["cochlea", "soc", "ic", "mgn", "a1"], "From the cochlea the signal climbs through the cochlear nuclei, the superior olive (where the two ears are first compared to locate sound), the inferior colliculus and the medial geniculate nucleus to the auditory cortex. It crosses at several levels, so each ear reaches both sides."),
  fig("fig-olfaction", R([...PER, "learning-motivation-emotion"], /olfact|sense of smell|smell (receptors?|perception|is the only)|anosmia|cribriform|pheromone|vomeronasal|mitral cells?|piriform/i), "olfaction", ["epithelium", "receptors", "bulb", "glomeruli", "tract"], "Smell receptors in the roof of the nose send fibres through the cribriform plate to the olfactory bulb, where they meet mitral cells in glomeruli. The tract goes straight to the piriform cortex and amygdala: the one sense that does not pass through the thalamus first."),
  fig("fig-taste", R([...PER, "learning-motivation-emotion"], /gustat|papillae|umami|taste (buds?|receptors?|cells?|qualit|perception|sensation|pathway)|chorda tympani|supertaster|ageusia|basic tastes?|five tastes/i), "taste", ["fungiform", "vallate", "foliate", "bud", "cells"], "Taste buds sit on the papillae of the tongue, each a cluster of receptor cells round a pore. The front two thirds sends taste in the facial nerve, the back third in the glossopharyngeal nerve, and the signals meet in the solitary nucleus of the medulla."),

  /* ------------------------------------------------ drugs at the synapse */
  fig("fig-ssri", R(PH, /^(?=[\s\S]*(\bssris?\b|selective serotonin|fluoxetine|sertraline|escitalopram|citalopram|paroxetine|fluvoxamine|vilazodone|vortioxetine|\bsert\b|serotonin transporter))(?=[\s\S]*(reuptake|transporter|\bsert\b|autoreceptor|5.ht1a|synap|delayed onset|weeks to (work|act|respond)|platelet))/i), "ssri-synapse", ["sert", "ssri", "auto", "rec"], "An SSRI blocks the serotonin transporter, so serotonin stays longer in the gap. At first the extra serotonin also hits the 5-HT1A autoreceptors that brake the neuron, which is one reason mood takes weeks to lift."),
  fig("fig-maoi", R(PH, /\bmaois?\b|monoamine oxidase inhibitors?|phenelzine|tranylcypromine|moclobemide|selegiline|isocarboxazid|\bmao.?[ab]\b|tyramine|cheese reaction/i, undefined, /switch|washout|wait (at least )?\d|gap/i), "maoi-synapse", ["mao", "maoi", "free", "ves"], "MAO sits on the mitochondria inside the nerve ending and breaks down spare monoamines. An MAOI blocks it, so more transmitter is stored and released. MAO in the gut also destroys dietary tyramine, which is why aged cheese can raise blood pressure dangerously on an irreversible MAOI."),
  fig("fig-tca", R(PH, /^(?=[\s\S]*(tricyclic|\btcas?\b|amitriptyline|imipramine|nortriptyline|clomipramine|dosulepin|desipramine|doxepin|trimipramine))(?=[\s\S]*(reuptake|block|receptor|muscarinic|anticholinergic|histamin|alpha.?1|sodium channel|\bqrs\b|cardiotox|fatal toxicity|mechanism))/i, undefined, /discover|paediatric|children|youth|bipolar|melitracen/i), "tca-synapse", ["sert", "net", "h1", "m1", "a1", "na"], "Tricyclics block both serotonin and noradrenaline reuptake (the wanted effect) and also histamine (sedation, weight), muscarinic (dry mouth, constipation, confusion), alpha-1 (dizziness on standing) and sodium channels (heart conduction, deadly in overdose)."),
  fig("fig-d2-block", R(PH, /d2 (receptors?|antagonis|block)|dopamine (antagonists?|receptor block|blockade|d2)|antipsychotics? (block|act|work)|mechanism of (action of )?(antipsychotic|haloperidol|chlorpromazine|risperidone)|5.ht2a.{0,30}(antagon|block)|serotonin.dopamine antagonist/i, undefined, /neuroleptic malignant|serotonin (syndrome|toxicity)|cyproheptadine/i), "antipsychotic-d2", ["d2", "block", "ht2a"], "An antipsychotic sits on postsynaptic D2 receptors so released dopamine cannot act. Many newer drugs also block 5-HT2A receptors, which frees some dopamine in the striatum and may lower movement side effects."),
  fig("fig-d2-occupancy", R(PH, /occupancy|(60|65|70|72|78|80) ?(%|per ?cent).{0,60}(d2|occupan|block)|therapeutic window.{0,60}(d2|antipsychotic|dopamine)|raclopride/i), "d2-occupancy", ["resp", "win", "eps", "prl"], "PET studies show response starts at about 60 to 65 percent D2 occupancy, while above about 80 percent movement side effects and prolactin rise sharply. Doses that sit in this window work with the fewest problems."),
  fig("fig-partial", R([...PH, "learning-motivation-emotion"], /partial agonis|intrinsic activity|full agonist|inverse agonist|dopamine stabili|agonist.{0,20}antagonist (properties|activity)|(aripiprazole|brexpiprazole|cariprazine|buspirone|varenicline|buprenorphine).{0,80}(partial|agonis|receptor|ceiling|stabili|lowers? (serum )?prolactin)/i), "partial-agonist", ["full", "part", "ant", "high", "low"], "A partial agonist switches the receptor on only part of the way. Where transmitter is high it competes it off and lowers the signal; where it is low it raises it. That is how aripiprazole calms psychosis with little stiffness, and why buprenorphine has a ceiling on breathing suppression."),
  fig("fig-gabaa", R(PH, /gaba.?a|benzodiazepine (receptor|site|binding)|chloride (channel|ion|influx)|flumazenil|alpha.?1 subunit|gamma.?2|positive allosteric|(anxiety|alcohol|ethanol).{0,60}\bgaba\b|\bgaba\b.{0,60}(anxiety|alcohol|ethanol)|(barbiturates?|z.drugs?|zolpidem|zopiclone|zaleplon|neurosteroids?|brexanolone|zuranolone|benzodiazepines?).{0,80}(receptor|binds?|subunit|mechanism|acts? (at|on|by|as|mainly)|chloride|\bgaba\b)/i), "benzo-gabaa", ["gaba", "bz", "pore", "alpha", "gamma"], "The GABA-A receptor is a ring of five units round a chloride pore. GABA binds between beta and alpha; benzodiazepines bind at a separate site between alpha and gamma-2 and make the pore open more often, so they need GABA to work. Barbiturates hold it open longer and can open it alone, which is why they are more dangerous."),
  fig("fig-nmda", R([...BX, "psychopharmacology"], /nmda|magnesium (block|plug)|glycine (site|co.?agonist)|(ketamine|esketamine|memantine|phencyclidine|\bpcp\b|dextromethorphan).{0,100}(block|antagon|receptor|channel|glutamate|mechanism)|(block|antagon|receptor|channel|glutamate|mechanism).{0,100}(ketamine|esketamine|memantine|phencyclidine|dextromethorphan)/i), "nmda-receptor", ["glu", "gly", "mg", "ket", "ca"], "The NMDA receptor needs two keys and an unplugged door: glutamate and glycine must both bind, and the magnesium plug must be pushed out by depolarisation. Then calcium floods in. Ketamine, PCP and memantine block it from inside the pore."),
  fig("fig-lithium", R(PH, /lithium.{0,80}(mechanism|inositol|gsk|second messenger|neuroprotect|how (does|it) works?|acts? (by|on)|enters)|inositol (depletion|monophosphatase)|gsk.?3|lithium.{0,40}(excreted|cleared) unchanged/i), "lithium-neuron", ["li", "impase", "gsk", "nach"], "Lithium enters neurons through sodium channels. Inside it blocks inositol recycling (damping overactive second messenger signals) and the enzyme GSK-3 beta (protecting cells). It is not metabolised: the kidney clears it unchanged, like sodium."),
  fig("fig-stimulant", R([...PH, "learning-motivation-emotion"], /^(?=[\s\S]*(methylphenidate|amphetamine|lisdexamfetamine|dexamfetamine|cocaine|stimulants?|dopamine transporter|vmat))(?=[\s\S]*(transporter|reuptake|releas|\bvmat|revers|mechanism|acts? (mainly )?by|works? (mainly )?by|prodrug))/i, undefined, /dat.?scan|ioflupane|spect/i), "stimulant-synapse", ["mph", "amph", "rev", "vmat"], "Methylphenidate and cocaine block the dopamine transporter from outside. Amphetamine enters through it, empties the vesicles (through VMAT) and runs the transporter backwards, pushing dopamine out even without a nerve signal."),
  fig("fig-pk-dose", R([...PH, "learning-motivation-emotion"], /\bcmax\b|\btmax\b|peak (plasma )?(level|concentration)|absorption phase|elimination (phase|half)|half.?li(fe|ves)|t ?1\/2|minimum effective concentration|plasma (level|concentration).{0,40}(time|rise|fall|peak)|first.order (kinetics|elimination)|zero.order|elimination rate/i, undefined, /steady.state|loading dose|fluorine|isotope|radioactive/i), "pk-single-dose", ["abs", "cmax", "half", "mec", "tox"], "After one dose the blood level rises while the tablet is absorbed, peaks (Cmax at Tmax), then falls by half every half-life. The drug works while the level sits between the minimum effective line and the toxic line."),
  fig("fig-pk-steady", R(PH, /steady.state|loading dose|(4|5|four|five)( to (5|five))? half.lives|accumulat(es|ion|ing)?.{0,40}(dose|days|half|level|repeated|renal|drug)|trough (level|concentration)|dosing interval|washout|therapeutic drug monitoring|\btdm\b/i, undefined, /seizure threshold/i), "pk-steady-state", ["acc", "ss", "load", "trough", "wash"], "Dosing once every half-life, the level climbs with each dose until intake equals removal: steady state, reached after about 4 to 5 half-lives. A loading dose gets there at once; stopping, it takes about as long to wash out."),
  fig("fig-cyp", R(PH, /\bcyp ?\d|cytochrome p450|cytochrome|enzyme induc|enzyme inhibit|glucuronid|\bugt\b|phase (i|ii|1|2) (metabolism|reactions?)|hepatic metabolism|first.pass/i, /cyp|interaction|polypharmacy|fdc|pharmacokinetics|clozapine|carbamazepine|hiv|integrative|lamotrigine|hepatic|valproate|smoking|epilepsy/), "liver-cell-cyp", ["cyp", "blocker", "ugt", "ser"], "In the liver cell, CYP enzymes in the smooth endoplasmic reticulum add oxygen to a drug and UGT then adds a sugar tag so the kidney or bile can remove it. An inhibitor blocks the CYP step and levels rise; an inducer makes more enzyme and levels fall."),

  /* ------------------------------------------------ EEG, sleep, stimulation */
  fig("fig-eeg-rhythms", R([...BX, "psychopharmacology", "indian-psychology", "positive"], /(alpha|beta|theta|delta|gamma) (waves?|rhythms?|activity|oscillations?|band)|eeg (rhythms?|frequenc|bands?|waves?)|(hz|cycles per second).{0,40}(eeg|alpha|beta|theta|delta)|alpha blocking|hans berger/i), "eeg-rhythms", ["beta", "alpha", "theta", "delta"], "Four EEG rhythms, slowest to fastest: delta (under 4 per second, deep sleep), theta (4 to 7, drowsiness), alpha (8 to 13, relaxed with eyes closed, blocked by opening them) and beta (over 13, alert thinking; benzodiazepines increase it)."),
  fig("fig-sleep-eeg", R([...BC, "cognitive"], /sleep spindles?|k.?complex|vertex (waves?|sharp)|sawtooth|slow.wave sleep|\bn1\b|\bn2\b|\bn3\b|stage (1|2|3|4|one|two|three|four) (of )?(sleep|nrem)|stages of sleep|rapid eye movement|\beog\b|polysomnograph/i, undefined, /apnoea|apnea|hypopn/i), "sleep-stage-eeg", ["alpha", "vertex", "spindle", "kc", "delta", "saw"], "Each sleep stage has its own EEG mark: alpha when drowsy, theta and vertex waves in N1, spindles and K complexes in N2, tall slow delta in N3, and low fast sawtooth waves with rapid eye movements in REM."),
  fig("fig-hypnogram", R([...BC, "cognitive", "health"], /hypnogram|sleep (cycles?|architecture)|90.minute|ultradian|rem latency|rem (periods?|rebound|density|pressure)|(first|early) (half|part|third) of the night|(later in the night|second half of the night|towards? (the )?morning)/i), "hypnogram", ["deep", "rem1", "cycle", "remlate"], "The night runs in cycles of about 90 minutes. Deep N3 sleep fills the first cycles; REM periods grow longer towards morning. In depression the first REM comes early (short REM latency) and deep sleep shrinks."),
  fig("fig-two-process", R([...BC, "health", "cognitive", "clinical-therapies"], /two.process|process s\b|process c\b|sleep pressure|homeostatic (sleep|drive|process)|adenosine|caffeine.{0,40}(sleep|adenosine|alert)|sleep (homeostasis|drive)|borb[eé]ly/i), "two-process-sleep", ["s", "c", "gate"], "Sleep pressure (process S, built by adenosine) rises all day and falls during sleep; the body clock (process C) keeps us alert until evening. Sleep comes easily when the two lines meet. Caffeine blocks adenosine, so it hides process S without removing it."),
  fig("fig-spike-wave", R([...BC, "psychometrics-assessment", "developmental"], /absence (seizures?|epilepsy)|petit mal|spike.and.(slow.)?wave|3 ?(hz|per second|cycles? per second)|ethosuximide|generali[sz]ed (spike|epileps)|epileptiform|interictal/i), "spike-wave", ["onset", "spike", "wave", "gen"], "In an absence seizure every EEG channel at once shows spike and slow wave at about 3 per second for a few seconds, then stops as suddenly. The child stares and stops, then carries on. Hyperventilation brings it on; ethosuximide and valproate treat it."),
  fig("fig-eeg-1020", R([...BX, "research-methods"], /10.20 (system|international|electrode)|eeg (electrodes?|montage|leads?)|electrodes?.{0,30}(scalp|eeg)|\bnasion\b|\binion\b|\bmontage/i, undefined, /\bect\b|electroconvulsive/i), "eeg-1020", ["nasion", "fp", "f3", "z", "c", "ear"], "EEG electrodes are placed at 10 and 20 percent steps between the nasion and inion and between the ears. Letters name the region (Fp, F, C, T, P, O), odd numbers are on the left, even on the right, and z marks the midline."),
  fig("fig-eeg-map", R(["psychometrics-assessment", "psychopathology", "clinical-psychiatry"], /\beeg\b.{0,60}(record|electrodes?|placed|scalp|montage|lead)|electroencephalogra.{0,60}(electrodes?|placed|scalp|record)/i, undefined, /\bect\b|electroconvulsive/i), "eeg-10-20", ["fp", "c", "t", "p", "o", "spacing"], "Seen from above, 19 electrodes are spaced at 10 and 20 percent of the head's measurements and named by brain region and side, so recordings from different labs can be compared."),
  fig("fig-tms", R(["psychopharmacology", "clinical-psychiatry", "biological", "clinical-therapies"], /\brtms\b|transcranial magnetic|\btms\b|theta.burst|figure.of.(eight|8) coil|motor threshold|5 ?cm rule|beam f3|neuronavigat/i, undefined, /hounsfield|regulatory|approval/i), "tms", ["coil", "dlpfc", "hotspot", "rule", "field"], "For depression the coil goes over the left dorsolateral prefrontal cortex. The dose is set from the motor threshold: the weakest pulse over the hand area that twitches the thumb. The 5 cm rule moves forward from that spot; the field reaches only the outer cortex."),
  fig("fig-ect", R(["psychopharmacology", "clinical-psychiatry", "clinical-therapies"], /bitemporal|bifrontal|right unilateral|unilateral (ect|electrode|placement)|d'?elia|electrode (placement|position)s?.{0,60}(ect|electroconvulsive)|(ect|electroconvulsive).{0,80}(electrodes?|placements?|bitemporal|unilateral|bifrontal)/i), "ect-placements", ["bt", "bf", "rultemp", "rulvertex", "rulpath"], "Three ECT placements: bitemporal (both temples, fastest and most memory loss), bifrontal (forehead, between the two), and right unilateral (right temple and near the top of the head, sparing the left language side, so least memory loss but needs a higher dose)."),
  fig("fig-ect-above", R(["ethics-law", "psychopathology", "counselling", "biological"], /bitemporal|bifrontal|right unilateral|unilateral (ect|electrode|placement)|d'?elia|electrode (placement|position)s?.{0,60}(ect|electroconvulsive)|(ect|electroconvulsive).{0,80}(electrodes?|placements?)/i), "ect-from-above", ["bt", "bf", "rul"], "The three ECT electrode placements seen from above: bitemporal on both temples, bifrontal on the forehead, and right unilateral on the right temple and near the crown, which spares memory most."),

  /* ------------------------------------------------ curves and scores */
  fig("fig-norm-scales", R([...STAT, "developmental", "clinical-psychiatry", "ugc-paper1"], /\bt[- ]scores?|\bz[- ]scores?|stanines?|\bstens?\b|percentile (rank|equivalent)s?|deviation iq|scaled scores?|standard scores?|mean (of )?100.{0,40}(sd|standard deviation) (of )?15|(sd|standard deviation) of 15|mean (of )?50.{0,40}(sd|standard deviation) (of )?10|normal (curve|distribution).{0,60}(per ?cent|%|area|standard deviation|percentile)|68.{0,15}95.{0,15}99|area (under the (normal )?curve )?(between|beyond|above|below) (the mean|z|a z)|proportion of (scores|cases).{0,40}(above|below|between)|empirical rule/i, undefined, /coefficient of variation|code type|base rate|\bmcmi\b/i), "normal-curve-scales", ["z", "t", "iq", "pct", "scaled", "sd"], "Every standard score is the same normal curve with a new ruler: z has mean 0 and SD 1, T mean 50 and SD 10, IQ mean 100 and SD 15, Wechsler subtests mean 10 and SD 3. One SD above the mean is about the 84th percentile on all of them."),
  fig("fig-sdt", R([...PER, "psychometrics-assessment", "research-methods", "clinical-psychiatry"], /signal detection|d.?prime|d′|false alarms?|correct rejections?|\bhits?\b.{0,40}(miss|false alarm)|response criterion|criterion.{0,30}(liberal|conservative|strict|lax)|(liberal|conservative) (criterion|responder)/i), "signal-detection", ["noise", "signal", "dprime", "crit", "hit", "fa"], "Noise alone and signal plus noise make two overlapping curves. Sensitivity (d prime) is the distance between their peaks; the criterion is where the person draws the line. Moving the line trades misses for false alarms without changing d prime."),
  fig("fig-roc", R(["psychometrics-assessment", "research-methods", "statistics", "clinical-psychiatry", "perception-attention", "psychopathology"], /\broc\b|receiver operating|area under the (roc )?curve|\bauc\b.{0,30}(roc|diagnos|\.\d|test)|cut.?offs?( (score|point)s?)?.{0,60}(sensitiv|specific|false (positive|alarm))|(sensitiv|specific).{0,60}cut.?offs?|youden/i), "roc-curve", ["chance", "d1", "d2", "strict", "lax", "auc"], "Each cut-off gives one hit rate and one false alarm rate; joining them makes the ROC curve. The diagonal is chance, a better test bows towards the top left, and the area under the curve (0.5 to 1) summarises accuracy across all cut-offs."),
  fig("fig-abab", R(["research-methods", "clinical-therapies", "learning-motivation-emotion", "psychometrics-assessment"], /\babab\b|reversal design|withdrawal design|\baba\b|a.b.a.b|baseline.{0,60}(withdraw|revers)/i), "abab-design", ["a1", "b1", "a2", "b2"], "Baseline, treatment, treatment withdrawn, treatment again. If the behaviour changes each time the phase changes, the treatment is the likely cause. It cannot be used when withdrawing treatment would be harmful or the change cannot reverse."),
  fig("fig-multiple-baseline", R(["research-methods", "clinical-therapies", "learning-motivation-emotion", "psychometrics-assessment"], /multiple.baseline|staggered (start|introduction|baselines?)/i), "multiple-baseline", ["base", "step", "p1", "p3"], "Treatment starts at a different time for each person (or behaviour or setting). Each one changes only when treatment reaches it, which rules out a coincidence in time without ever withdrawing treatment."),
  fig("fig-factorial", R(["statistics", "research-methods"], /factorial (design|anova|experiment|analysis)|\d ?× ?\d( ?× ?\d)? (factorial|design|between|within|mixed|anova)|interaction effect|main effects?|2 ?(x|×|by) ?2 (factorial|design|anova|between|within|mixed)|two.way (anova|analysis of variance)|crossover interaction|ordinal interaction|non.?parallel lines|simple (main )?effects|interaction (between|of) (the )?(two )?(factors|variables|independent)/i, undefined, /external validity|campbell|chi.square|χ²|contingency/i), "factorial-interaction", ["mainA", "mainB", "inter", "parallel"], "Plot the cell means as lines. A gap between the lines is a main effect of one factor, a slope is a main effect of the other, and lines that are not parallel mean an interaction: the effect of one factor depends on the level of the other."),
  fig("fig-serial-position", R(["cognitive", "developmental", "learning-motivation-emotion", "history-systems"], /serial position|primacy (effect)?|recency (effect)?|glanzer|cunitz|murdock|free recall.{0,60}(list|position|first|last)/i), "serial-position", ["primacy", "recency", "middle", "delay"], "In free recall the first words (primacy, rehearsed into long-term memory) and the last words (recency, still in short-term memory) are remembered best. A 30-second distracting delay removes recency but leaves primacy."),
  fig("fig-forgetting", R(["cognitive", "history-systems", "learning-motivation-emotion", "developmental"], /forgetting curve|ebbinghaus(?!.{0,10}illusion)|savings (method|score)|method of savings|nonsense syllables?|spacing effect|spaced (practice|review|repetition|learning)|distributed practice|massed (vs\.?|versus|and) (spaced|distributed)/i, undefined, /infant|segmentation|statistical learning/i), "forgetting-curve", ["steep", "flat", "savings", "review"], "Ebbinghaus learned nonsense syllables and measured savings when relearning. Most forgetting happens in the first hour and day, then the curve flattens. Each spaced review makes the next curve shallower."),
  fig("fig-yerkes", R(["learning-motivation-emotion", "health", "perception-attention", "organisational", "social", "positive", "clinical-therapies", "cognitive"], /yerkes|dodson|inverted.u|optimal (level of )?arousal|arousal.{0,30}performance|performance.{0,30}arousal/i), "yerkes-dodson", ["simple", "complex", "opt"], "Performance rises with arousal up to a point and then falls. For a hard task the peak comes at a lower level of arousal than for an easy one, which is why exam nerves hurt complex reasoning more than simple recall."),
  fig("fig-stress-vuln", R(CLIN, /stress.vulnerability|diathesis.stress|vulnerability.stress|zubin|vulnerability model/i), "stress-vulnerability", ["thr", "hv", "lv", "ill", "well"], "Each person has a threshold. With high vulnerability little stress is enough to tip into illness; with low vulnerability it takes a great deal. Treatment works on both axes: medicine and skills raise the threshold, and lowering stress keeps a person below it."),

  /* ------------------------------------------------ learning */
  fig("fig-schedules", R(LRN, /schedules? of reinforcement|reinforcement schedules?|fixed.ratio|variable.ratio|fixed.interval|variable.interval|\b(fr|vr|fi|vi)[ -]?\d+\b|scallop|cumulative record|post.reinforcement pause|ratio strain|partial reinforcement (extinction )?effect/i), "reinforcement-schedules", ["vr", "fr", "vi", "fi"], "Cumulative records rise faster the faster the animal responds. Ratio schedules give fast responding; fixed schedules give a pause after each reward (a step for FR, a scallop for FI); variable schedules give steady responding that is hardest to extinguish."),
  fig("fig-pavlov", R(LRN, /pavlov|salivat|metronome|dogs?.{0,40}(bell|food|saliva)/i), "pavlov-apparatus", ["met", "food", "meas"], "Pavlov's dog stood in a harness with a tube from its cheek measuring saliva. A metronome (the neutral stimulus) sounded just before food arrived; after a few pairings the sound alone made the dog salivate."),
  fig("fig-skinner-box", R(LRN, /skinner box|operant chamber|lever.?press|key.?peck|shaping|successive approximations?|discriminative stimulus|\bs\^?d\b|pigeons?.{0,40}(peck|key|reinforc)|rats?.{0,40}lever|cumulative recorder/i), "skinner-box", ["lever", "disp", "tray", "light", "rec"], "In the operant chamber a rat presses a lever and food drops into the tray. A light or tone can signal when pressing pays, and a recorder outside counts every press, giving the cumulative record."),
  fig("fig-little-albert", R([...LRN, "psychopathology", "ethics-law", "research-methods"], /little albert|watson and rayner|rayner|white rat|conditioned emotional (reaction|response)|conditioned fear in (an|a) (infant|child|baby)/i), "little-albert", ["rat", "bar", "fear", "gen", "ethics"], "Watson and Rayner struck a steel bar behind baby Albert whenever he touched a white rat. After a few pairings the rat alone made him cry, and the fear spread to a rabbit, a dog and a fur coat: stimulus generalisation. The fear was never removed."),
  fig("fig-bobo", R(["learning-motivation-emotion", "social", "developmental", "personality-theories"], /bobo|bandura.{0,60}(aggress|doll|model|imitat)|observational learning|vicarious (reinforcement|punishment|learning)|imitat(e|ed|ion) (of )?(the )?aggress|social learning theory.{0,40}(aggress|model)/i), "bobo-doll", ["model", "mallet", "bobo", "copy"], "Children watched an adult hit and kick a large Bobo doll; later, alone with it, they copied the same acts and words. Learning happened by watching, without any reward to the child."),

  /* ------------------------------------------------ development */
  fig("fig-strange-room", R(["developmental", "personality-theories", "counselling", "clinical-therapies", "psychopathology", "clinical-psychiatry", "social"], /strange situation|ainsworth|separation and reunion|reunion (episode|behaviou?r)|eight episodes/i, undefined, /adult attachment|hazan|shaver|romantic/i), "strange-situation-room", ["mom", "str", "baby", "toys", "mirror", "door"], "The Strange Situation takes place in a playroom watched through a one-way mirror. Across eight short episodes the mother leaves and returns and a stranger comes in; the key is how the baby greets the mother at reunion."),
  fig("fig-visual-cliff", R(["developmental", "perception-attention", "cognitive"], /visual cliff|gibson and walk|walk and gibson|depth perception.{0,60}(infant|baby|crawl)|social referencing/i, undefined, /held and hein|kitten|carousel/i), "visual-cliff", ["shallow", "deep", "infant", "mother"], "A checkerboard lies just under the glass on one side and far below on the other. Most crawling babies will not cross the apparent drop even when the mother calls, so depth perception is present by the time they crawl; many look at the mother's face first, which is social referencing."),
  fig("fig-harlow", R(["developmental", "learning-motivation-emotion", "personality-theories", "history-systems", "social"], /harlow|wire (and|vs\.?|versus) cloth|cloth (mother|surrogate)|wire (mother|surrogate)|contact comfort/i, undefined, /learning sets?|learning to learn|discrimination problems/i), "harlow-mothers", ["wire", "bottle", "cloth", "infant"], "Infant monkeys spent most of their time clinging to a soft cloth mother even when only the wire mother held the bottle. Comfort, not food, was the basis of attachment, against the cupboard love view."),
  fig("fig-three-mountains", R(["developmental", "cognitive", "history-systems"], /three.mountains?|perspective.taking|policeman doll|hughes.{0,20}(policeman|doll)|egocentri(sm|c)(?! (in )?adolescen)/i, undefined, /imaginary audience|personal fable|adolescent egocentri/i), "three-mountains", ["child", "doll", "snow", "hut", "cross"], "The child sits on one side of a model of three mountains and must pick the picture of what a doll on another side sees. Before about seven children tend to pick their own view: Piaget's egocentrism. Simpler, more familiar versions show it much earlier."),
  fig("fig-conservation", R(["developmental", "cognitive", "history-systems"], /conservation (of )?(liquid|volume|quantity)|tall (thin|narrow) (glass|beaker|container)|pour(ed|ing).{0,40}(glass|beaker|container)|centration|reversibility|compensation (argument|reasoning)|decentr/i), "conservation-liquid", ["same", "pour", "tall", "rev", "comp"], "The same water poured into a tall thin glass looks like more. A preoperational child centres on the height and says it has more; a concrete operational child conserves, reasoning that it can be poured back (reversibility) or that the glass is thinner (compensation)."),

  /* ------------------------------------------------ social studies */
  fig("fig-milgram", R(SOC, /milgram|shock generator|450 ?v|teacher.{0,40}learner|agentic state|obedience (study|experiment|research)/i, undefined, /urban overload|mono.operation/i), "milgram-setup", ["teacher", "exp", "gen", "learner", "s450"], "The real participant is the teacher at a generator with 30 switches from 15 to 450 volts; the learner, a confederate, is in the next room and is never shocked. The experimenter in a grey coat stays beside the teacher with set prods."),
  fig("fig-asch", R(SOC, /asch|line (judgement|judgment|length|task)|comparison lines?|confederates?.{0,60}(wrong|incorrect|line)|conformity.{0,60}(line|unanim|group size)/i, undefined, /warm.?cold|central traits?|impression formation/i), "asch-cards", ["std", "cmp", "right", "conf", "part"], "Asch showed a standard line and three comparison lines with an obvious answer. Seven confederates gave the same wrong answer first; the real participant, near the end, went along on about a third of these trials, and far less when one ally broke the majority."),

  /* ------------------------------------------------ perception */
  fig("fig-muller", R(PER, /m[uü]ller.?lyer|carpentered|arrowheads?|outward fins|inward fins/i), "muller-lyer", ["short", "long", "same", "culture"], "The two lines are the same length. The one with outward fins looks longer; one explanation is misapplied size constancy from corners in a carpentered world, which is why the illusion is weaker in some people raised with fewer straight-edged buildings."),
  fig("fig-ponzo", R(PER, /ponzo|railway (lines|tracks)|converging lines/i), "ponzo", ["rails", "far", "near"], "Two equal bars between converging railway lines: the upper one seems farther away, so the brain scales it up and it looks longer. Linear perspective is being applied to a flat picture."),
  fig("fig-ames", R(PER, /ames (room|window)|ames'? (distorted )?room/i), "ames-room", ["real", "seen", "far", "near", "peep"], "The Ames room is a trapezoid with one back corner much farther away, but through the peephole it looks rectangular. Because the room seems normal, people in the far corner look tiny: we keep the room's shape and give up size constancy."),
  fig("fig-kanizsa", R(PER, /kanizsa|illusory contours?|subjective contours?|(law|principle) of closure|closure (principle|law)|gestalt.{0,30}closure/i), "kanizsa-triangle", ["pac", "illusory", "closure"], "Three cut discs and three angles make us see a bright white triangle whose edges are not drawn: closure. The visual system fills in the most likely whole shape."),
  fig("fig-stroop", R(["cognitive", "perception-attention", "psychometrics-assessment", "biological", "clinical-psychiatry", "psychopathology"], /stroop|colou?r.word (test|task|interference)|ink colou?r|naming the (ink|colou?r)|emotional stroop/i), "stroop-card", ["cong", "inc", "auto", "int"], "Naming the ink colour is slow when the word names a different colour, because reading is automatic and has to be held back. The test measures selective attention and inhibition, which rely on the anterior cingulate and prefrontal cortex."),

  /* ------------------------------------------------ memory, motivation, personality */
  fig("fig-maslow", R(["learning-motivation-emotion", "personality-theories", "organisational", "history-systems", "counselling", "positive", "ugc-paper1"], /maslow'?s? (hierarchy|pyramid|needs|theory of (human )?motivation|levels?)|hierarchy of needs|need hierarchy|erg theory|alderfer|deficiency needs|growth needs|\b(d|b).needs|esteem needs|safety needs|physiological needs|belongingness( and love)? needs|self.actuali[sz]ation needs/i), "maslow-pyramid", ["phys", "safety", "love", "esteem", "self", "deficit", "growth"], "Maslow's pyramid runs from physiological needs at the base through safety, love and belonging and esteem (the deficiency needs) to self-actualisation at the top (a growth need). Lower needs usually press first, though the order is looser in real life than the pyramid suggests."),
  fig("fig-wm", R(["cognitive", "developmental", "perception-attention", "history-systems", "ugc-paper1"], /working memory model|baddeley|hitch|phonological (loop|store)|visuo.?spatial (sketchpad|scratchpad)|central executive|episodic buffer|articulatory (suppression|control|rehearsal|loop)|word.length effect|inner (scribe|cache)|phonological similarity effect/i, undefined, /godden|divers|context.dependent/i), "working-memory-model", ["ce", "pl", "vss", "eb", "art"], "Baddeley's working memory has a central executive directing two slave systems, the phonological loop for sounds and words and the visuospatial sketchpad for images, plus the episodic buffer that binds them and links to long-term memory."),
  fig("fig-msm", R(["cognitive", "developmental", "perception-attention", "history-systems", "ugc-paper1", "learning-motivation-emotion"], /multi.?store|atkinson.{0,12}shiffrin|modal model|sensory (register|memory|store)|maintenance rehearsal|iconic (memory|store)|echoic (memory|store)|sperling|partial report/i), "multi-store-model", ["sr", "att", "stm", "reh", "ltm", "ret"], "In the multi-store model information enters a large but brief sensory register, attention moves some into short-term memory (about 7 items for about 20 seconds), and rehearsal moves it into long-term memory, from which it is retrieved back into short-term memory for use."),
  fig("fig-eysenck", R(["personality-theories", "psychometrics-assessment", "history-systems"], /eysenck|extraver|introver|neuroticism|psychoticism|melancholic|choleric|sanguine|phlegmatic|four (humou?rs|temperaments)|galen|hippocrat.{0,30}(humou?r|temperament)/i, undefined, /big five|five.factor|\bocean\b|neo.pi|openness|conscientious|agreeable|hexaco|jung|psychotherapy|1952|16pf|narcissis|rorschach|erlebnistypus|twin|heritab|rank.order/i), "eysenck-circle", ["e", "n", "p", "mel", "cho", "san", "phl"], "Eysenck crossed introversion to extraversion with stable to unstable. The four quadrants match the ancient temperaments: unstable introvert melancholic, unstable extravert choleric, stable extravert sanguine and stable introvert phlegmatic. Psychoticism was added later as a third dimension."),
  fig("fig-genogram", R(["clinical-therapies", "counselling", "psychopathology", "clinical-psychiatry", "developmental"], /genogram|family tree|multigenerational (transmission|pattern)|three.generation/i), "genogram-symbols", ["male", "female", "index", "married", "divorced", "conflict", "cutoff"], "Genogram symbols: squares for males, circles for females, a double outline for the index person, a cross for a death, lines for marriage, slashes for separation and divorce, and zigzag or broken lines for conflict and emotional cut-off."),
  fig("fig-clock", R(["psychometrics-assessment", "clinical-psychiatry", "psychopathology", "cognitive", "biological"], /clock (drawing|test)|draw(ing)? a clock|intersecting pentagons|pentagons|constructional (apraxia|ability|praxis|dyspraxia)|(\bmmse\b|mini.mental|\bmoca\b|montreal cognitive|\bace.?(iii|r)\b|addenbrooke).{0,80}(items?|subtests?|domains?|copy|draw|visuospatial|executive|pentagon|clock|scored out of|maximum score|points)/i), "copy-and-clock", ["pent", "overlap", "clock", "hands", "bunched"], "Two bedside drawing tasks: copying intersecting pentagons tests visuospatial construction (the overlap must make a four-sided shape), and drawing a clock at ten past eleven also tests planning. Bunched numbers or hands pointing to 10 and 11 suggest executive problems."),
  fig("fig-mhca", R(["ethics-law", "clinical-psychiatry"], /supported admission|independent admission|section (86|87|88|89|90|94|98)\b|emergency (treatment|care).{0,60}(72|seventy.two) hours|(72|seventy.two) hours.{0,60}emergency|admission.{0,60}(30|90|120|180|thirty|ninety) days|(30|90|120|180|thirty|ninety) days.{0,60}admission|minors?.{0,40}admission|admission of (a )?minors?/i, undefined, /bharatiya|nyaya|\bbns\b|\bipc\b/i), "mhca-time-limits", ["indep", "emerg", "s89", "s90", "minor"], "The Mental Healthcare Act 2017 time limits drawn to scale: emergency treatment up to 72 hours, supported admission under section 89 up to 30 days, then under section 90 up to 90 days, renewable for 120 and then 180 days, with the Review Board told and able to review."),
  /* ------------------------------------------------ disorders on the real anatomy */
  fig("fig-alzheimer", R(["psychopathology", "clinical-psychiatry", "cognitive", "biological", "psychometrics-assessment", "psychopharmacology"], /alzheimer.{0,120}(hippocamp|medial temporal|entorhinal|atroph|neurofibrillary|tangles|braak)|(hippocamp|medial temporal|entorhinal).{0,120}alzheimer/i), "hippocampus", ["parahip", "dg", "ammon", "subiculum"], "Alzheimer's disease begins in the entorhinal cortex and hippocampus: tangles appear there first, the medial temporal lobe shrinks on MRI, and the first symptom is trouble forming new memories."),
  fig("fig-ftd", R(["psychopathology", "clinical-psychiatry", "cognitive", "biological", "psychometrics-assessment"], /frontotemporal|\bftd\b|bvftd|pick'?s disease|semantic dementia|primary progressive aphasia/i), "brain-lateral", ["frontal", "temporal"], "Frontotemporal dementia shrinks the frontal and front temporal lobes and spares the back of the brain. Frontal damage changes personality and conduct first; left temporal damage takes away word meaning (semantic dementia)."),
  fig("fig-wernicke-korsakoff", R(["psychopathology", "clinical-psychiatry", "psychopharmacology", "biological", "cognitive"], /wernicke'?s? encephalopathy|wernicke.korsakoff|korsakoff|thiamine/i, undefined, /symptom.triggered|chlordiazepoxide|oral thiamine|withdrawal regimen/i), "limbic-system", ["mammillary", "mtt", "anteriorthal", "fornix"], "Thiamine lack damages the mammillary bodies and the thalamus, two stops on the memory circuit from the hippocampus. That is why Korsakoff's syndrome leaves a person unable to form new memories and filling the gaps with confabulation."),
  fig("fig-anticholinergic", R(PH, /anticholinergic (toxicity|syndrome|toxidrome|side.effects?|burden|effects?|delirium)|antimuscarinic|physostigmine|muscarinic (block|antagon)|dry mouth.{0,40}(urinary|constipation|blurred)|urinary retention/i), "autonomic", ["cn3", "vagus", "sacral", "pupil", "saliva", "bladder"], "Anticholinergic drugs block the parasympathetic side of the autonomic system: no saliva (dry mouth), wide pupils and blurred near vision, a fast heart, a slow gut and a bladder that will not empty. In the brain the same block gives confusion."),
  fig("fig-ocd-loop", R(["psychopathology", "clinical-psychiatry", "biological", "clinical-therapies", "psychopharmacology"], /(\bocd\b|obsessive.compulsive).{0,120}(circuit|caudate|striat|orbitofrontal|basal ganglia|capsulotomy|deep brain|thalam)|cortico.?striato.?thalam/i), "basal-ganglia-circuit", ["cortex", "striatum", "thalamus", "tc"], "OCD is linked to a loop from the orbitofrontal cortex to the caudate, on to the thalamus and back to the cortex. The loop is overactive on scans and settles with successful SSRI treatment or exposure therapy; capsulotomy and deep brain stimulation interrupt it in the most severe cases."),
  fig("fig-ptsd-circuit", R(["psychopathology", "clinical-psychiatry", "biological", "clinical-therapies", "health"], /(ptsd|post.traumatic).{0,120}(amygdala|prefrontal|hippocamp|fear (extinction|circuit|conditioning)|neurobiolog|brain)|fear extinction|extinction learning/i), "amygdala-fear", ["amygdala", "vmpfc", "hippocampus", "brake"], "In PTSD the amygdala is overactive while the ventromedial prefrontal cortex, which normally applies the brake, and the hippocampus, which tags fear to the right context, are underactive. Exposure therapy works by building new extinction learning in this circuit."),
  fig("fig-reward", R(["learning-motivation-emotion", "psychopathology", "clinical-psychiatry", "psychopharmacology", "cognitive", "health"], /reward (pathway|circuit|system)|mesolimbic|nucleus accumbens|ventral striatum|incentive salience|reward prediction error|(addiction|drugs? of abuse|substance use).{0,80}(dopamine|reward)|dopamine.{0,80}(addiction|reward|craving)/i), "dopamine-pathways", ["vta", "mesolimbic", "accumbens"], "Every addictive drug raises dopamine from the ventral tegmental area in the nucleus accumbens, along the mesolimbic pathway. This system signals that something matters and is worth repeating; with repeated use it responds to cues and craving more than to the drug itself."),
  fig("fig-snri", R(PH, /^(?=[\s\S]*(\bsnris?\b|venlafaxine|duloxetine|desvenlafaxine|milnacipran|levomilnacipran|atomoxetine|reboxetine))(?=[\s\S]*(reuptake|transporter|block|mechanism|noradrenaline|norepinephrine))/i, undefined, /tricyclic/i), "tca-synapse", ["sert", "net"], "SNRIs block the same two pumps as the tricyclics, for serotonin and for noradrenaline, but leave the side doors (histamine, muscarinic, alpha-1 and sodium channels) alone, so they are safer in overdose. Atomoxetine and reboxetine block only the noradrenaline pump."),
  fig("fig-gate-control", R(["perception-attention", "health", "biological", "learning-motivation-emotion"], /gate control|substantia gelatinosa|dorsal horn|melzack and wall|a.delta|c.fibres?|nociceptors?.{0,60}(spinal|dorsal|cord)|spinothalamic/i), "spinal-cord", ["droot", "grey", "spinothal", "drg"], "Pain fibres (fast A-delta and slow C fibres) enter through the dorsal root to the dorsal horn, where Melzack and Wall placed the gate. Touch input and signals coming down from the brain can close it; the message then crosses and rises in the spinothalamic tract."),
  fig("fig-colour", R(["perception-attention", "biological", "cognitive", "developmental"], /trichromat|young.helmholtz|three (types of )?cones|cone (types|cells|pigments)|colou?r (blindness|deficien)|protanop|deuteranop|tritanop|dichromat|rods? (are|work|for) (dim|night)|scotopic|photopic|dark adaptation|purkinje shift/i, undefined, /x.linked|recessive|chromosome/i), "eye", ["retina", "fovea"], "Colour starts in the retina. Three kinds of cone, most packed into the fovea, respond best to short, middle and long wavelengths; rods take over in dim light but see no colour. Losing one cone type gives the common red-green colour blindness."),
  fig("fig-parasomnia", R(["biological", "clinical-psychiatry", "psychopathology", "health", "clinical-therapies"], /sleepwalking|somnambulism|(night|sleep) terrors?|nightmare disorder|rem sleep behaviou?r disorder|\brbd\b|confusional arousals?|nrem (arousal|parasomnia)/i, undefined, /lewy/i), "hypnogram", ["deep", "remlate", "cycle"], "Sleepwalking and sleep terrors come out of deep N3 sleep, so they happen in the first third of the night. Nightmares and REM sleep behaviour disorder come out of REM, which is longest towards morning."),
  fig("fig-cs-us", R(LRN, /unconditioned (stimulus|response)|conditioned (stimulus|response)|\bucs\b|\bucr\b|\bcs\b.{0,40}\bus\b|\bus\b.{0,40}\bcs\b|neutral stimulus/i, undefined, /little albert|watson|taste aversion|garcia/i), "pavlov-apparatus", ["met", "food", "meas"], "Pavlov's set-up names every part of classical conditioning: food in the mouth is the unconditioned stimulus and salivating to it the unconditioned response; the metronome starts as a neutral stimulus and, once paired with food, becomes the conditioned stimulus that makes the dog salivate on its own, the conditioned response."),
  fig("fig-monoamine", R(["psychopathology", "clinical-psychiatry", "biological", "psychopharmacology"], /monoamine (hypothesis|deficiency|theory)|serotonin (hypothesis|deficiency)|catecholamine hypothesis|chemical imbalance|reserpine/i), "synapse", ["vesicle", "transmitter", "receptor", "transporter", "autoreceptor"], "The monoamine hypothesis said depression is too little serotonin or noradrenaline at the synapse: reserpine, which empties the vesicles, could cause low mood, and antidepressants that block reuptake raise the transmitter. But they do so within hours while mood lifts over weeks, so slower changes in receptors and plasticity must matter too."),
];
